import React, { useState, useEffect } from 'react';
import { NavLink, useLocation, useNavigate } from 'react-router-dom';
import { Menu, X, Phone, Mail, Facebook, Twitter, Linkedin, Instagram } from 'lucide-react';
import { COMPANY_NAME, NAV_ITEMS, CONTACT_EMAIL, CONTACT_PHONE } from '../../constants';

const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const location = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 20) {
        setScrolled(true);
      } else {
        setScrolled(false);
      }
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleNavClick = (path: string) => {
    setIsOpen(false);
    // If using hash router or internal anchors in a single page flow
    // For this implementation, we use standard routing but scroll to top
    window.scrollTo(0, 0);
  };

  return (
    <header className="fixed w-full z-50 transition-all duration-300">
      {/* Top Bar */}
      <div className={`bg-primary-900 text-white text-sm py-2 px-4 transition-all duration-300 ${scrolled ? 'h-0 overflow-hidden py-0' : 'h-auto'}`}>
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center space-y-2 md:space-y-0">
          <div className="flex items-center space-x-6">
            <a href={`mailto:${CONTACT_EMAIL}`} className="flex items-center space-x-2 hover:text-accent-500 transition-colors">
              <Mail size={14} />
              <span>{CONTACT_EMAIL}</span>
            </a>
            <a href={`tel:${CONTACT_PHONE}`} className="flex items-center space-x-2 hover:text-accent-500 transition-colors">
              <Phone size={14} />
              <span>{CONTACT_PHONE}</span>
            </a>
          </div>
          <div className="flex items-center space-x-4">
            <span className="hidden md:inline text-gray-400 mr-2">Follow Us:</span>
            <a href="#" className="hover:text-accent-500 transition-colors"><Facebook size={14} /></a>
            <a href="#" className="hover:text-accent-500 transition-colors"><Twitter size={14} /></a>
            <a href="#" className="hover:text-accent-500 transition-colors"><Linkedin size={14} /></a>
            <a href="#" className="hover:text-accent-500 transition-colors"><Instagram size={14} /></a>
          </div>
        </div>
      </div>

      {/* Main Nav */}
      <div className={`shadow-lg transition-all duration-300 ${scrolled ? 'bg-white py-2' : 'bg-white/95 backdrop-blur-md py-4'}`}>
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center">
            {/* Logo */}
            <div className="flex items-center cursor-pointer" onClick={() => navigate('/')}>
              <div className="bg-primary-900 text-white p-2 rounded-lg mr-2 font-bold text-xl tracking-tighter">
                UG
              </div>
              <div>
                <h1 className="text-2xl font-serif font-bold text-primary-900 tracking-tight leading-none">
                  {COMPANY_NAME}
                </h1>
                <p className="text-[10px] text-gray-500 font-bold tracking-widest uppercase hidden sm:block">
                  Traders & Engineers
                </p>
              </div>
            </div>

            {/* Desktop Menu */}
            <nav className="hidden md:flex space-x-8">
              {NAV_ITEMS.map((item) => (
                <NavLink
                  key={item.path}
                  to={item.path}
                  onClick={() => handleNavClick(item.path)}
                  className={({ isActive }) =>
                    `text-sm font-semibold tracking-wide uppercase transition-colors duration-200 ${
                      isActive ? 'text-accent-600 border-b-2 border-accent-600' : 'text-primary-900 hover:text-accent-600'
                    }`
                  }
                >
                  {item.label}
                </NavLink>
              ))}
            </nav>

            {/* Quote Button */}
            <div className="hidden md:block">
              <button 
                onClick={() => navigate('/contact')}
                className="bg-accent-500 hover:bg-accent-600 text-white px-6 py-2.5 rounded-full text-sm font-semibold transition-transform transform hover:scale-105 shadow-md"
              >
                Get a Quote
              </button>
            </div>

            {/* Mobile Menu Button */}
            <div className="md:hidden flex items-center">
              <button
                onClick={() => setIsOpen(!isOpen)}
                className="text-primary-900 hover:text-accent-600 focus:outline-none"
              >
                {isOpen ? <X size={28} /> : <Menu size={28} />}
              </button>
            </div>
          </div>
        </div>

        {/* Mobile Menu */}
        <div className={`md:hidden absolute w-full bg-white shadow-xl transition-all duration-300 ease-in-out origin-top ${isOpen ? 'scale-y-100 opacity-100' : 'scale-y-0 opacity-0 h-0 overflow-hidden'}`}>
          <div className="px-4 pt-2 pb-6 space-y-2 flex flex-col items-center">
            {NAV_ITEMS.map((item) => (
              <NavLink
                key={item.path}
                to={item.path}
                onClick={() => handleNavClick(item.path)}
                className={({ isActive }) =>
                  `block px-3 py-3 text-base font-medium w-full text-center rounded-md ${
                    isActive ? 'text-accent-600 bg-gray-50' : 'text-gray-700 hover:text-accent-600 hover:bg-gray-50'
                  }`
                }
              >
                {item.label}
              </NavLink>
            ))}
             <button 
                onClick={() => { navigate('/contact'); setIsOpen(false); }}
                className="mt-4 w-full bg-accent-500 text-white px-6 py-3 rounded-lg text-sm font-bold uppercase"
              >
                Request Quote
              </button>
          </div>
        </div>
      </div>
    </header>
  );
};

export default Navbar;

import React, { useState, useEffect } from 'react';
import { ArrowRight } from 'lucide-react';
import { HERO_SLIDES } from '../constants';
import { useNavigate } from 'react-router-dom';

const Hero: React.FC = () => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const navigate = useNavigate();

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % HERO_SLIDES.length);
    }, 6000);
    return () => clearInterval(timer);
  }, []);

  return (
    <div className="relative h-[600px] md:h-[750px] overflow-hidden bg-primary-900">
      {/* Slides */}
      {HERO_SLIDES.map((slide, index) => (
        <div
          key={index}
          className={`absolute inset-0 transition-opacity duration-1000 ease-in-out ${
            index === currentSlide ? 'opacity-100' : 'opacity-0'
          }`}
        >
          {/* Image */}
          <div 
            className="absolute inset-0 bg-cover bg-center transform transition-transform duration-[8000ms] scale-105 hover:scale-110"
            style={{ backgroundImage: `url(${slide.image})` }}
          />
          {/* Overlay */}
          <div className="absolute inset-0 bg-black/40 bg-gradient-to-r from-black/70 to-transparent" />

          {/* Content */}
          <div className="absolute inset-0 flex items-center">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 w-full">
              <div className={`max-w-2xl transform transition-all duration-1000 delay-300 ${
                index === currentSlide ? 'translate-y-0 opacity-100' : 'translate-y-10 opacity-0'
              }`}>
                <h2 className="text-accent-500 font-bold tracking-widest uppercase mb-4 text-sm md:text-base">
                  United Global Traders and Engineers
                </h2>
                <h1 className="text-4xl md:text-6xl font-serif font-bold text-white mb-6 leading-tight">
                  {slide.title}
                </h1>
                <p className="text-gray-200 text-lg md:text-xl mb-8 border-l-4 border-accent-500 pl-4">
                  {slide.subtitle}
                </p>
                <button 
                  onClick={() => navigate('/products')}
                  className="bg-accent-500 hover:bg-accent-600 text-white px-8 py-3 rounded-md font-semibold text-lg transition-all flex items-center group"
                >
                  {slide.cta}
                  <ArrowRight className="ml-2 group-hover:translate-x-1 transition-transform" />
                </button>
              </div>
            </div>
          </div>
        </div>
      ))}

      {/* Dots */}
      <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 flex space-x-3">
        {HERO_SLIDES.map((_, index) => (
          <button
            key={index}
            onClick={() => setCurrentSlide(index)}
            className={`w-3 h-3 rounded-full transition-all duration-300 ${
              index === currentSlide ? 'bg-accent-500 w-8' : 'bg-white/50 hover:bg-white'
            }`}
          />
        ))}
      </div>
    </div>
  );
};

export default Hero;

